import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import {
  ComposedModal,
  ModalHeader,
  ModalBody,
  ModalFooter,
  TextInput,
  Button,
} from 'carbon-components-react';

function ModalWidthRegression() {
  const [open, setOpen] = useState(false);

  return (
    <>
      <Button kind="primary" onClick={() => setOpen(true)}>
        Open modal
      </Button>
      {typeof document !== 'undefined' &&
        ReactDOM.createPortal(
          <ComposedModal
            open={open}
            onClose={() => setOpen(false)}
            size="lg"
          >
            <ModalHeader
              label="Label"
              title="Modal heading"
            />
            {/*
              According to the design guidelines, hasForm removes the 20% right
              padding so that form controls are full width. With the regression,
              TextInput will still be inset.
            */}
            <ModalBody hasForm>
              <TextInput
                id="domain-name"
                labelText="Domain name"
                placeholder="e.g. github.com"
              />
            </ModalBody>
            <ModalFooter
              secondaryButtonText="Cancel"
              primaryButtonText="Save"
            />
          </ComposedModal>,
          document.body
        )}
    </>
  );
}

export default ModalWidthRegression;
